<template>
 <view class="coach">
  <view class="coach-heading"><text class="coach-kicker">FITSTREAK / AI COACH</text><text class="coach-title">{{ct('title')}}</text><text class="coach-subtitle">{{ct('intro')}}</text></view>
  <view v-if="error" class="coach-error"><text>{{ct(error)}}</text><button role="button" tabindex="0" class="coach-link" @click="initialize">{{ct('retry')}}</button></view>
  <view class="coach-layout">
   <view class="coach-profile coach-panel">
    <text class="coach-section-title">{{ct('profile')}}</text><text class="coach-hint">{{ct('profileHint')}}</text>
    <view class="coach-fields"><view v-for="f in numericFields" :key="f.key" class="coach-field" :class="'health-'+f.key"><text>{{ct(f.label)}}</text><input type="digit" v-model="form[f.key]" :aria-label="ct(f.label)" :disabled="busy" :aria-disabled="busy"/></view></view>
    <view class="coach-field"><text>{{ct('goal')}}</text><view class="coach-choices"><button v-for="g in ['fitness','strength','weight_management']" :key="g" role="button" tabindex="0" :aria-pressed="form.goal===g" :class="{selected:form.goal===g}" :disabled="busy" :aria-disabled="busy" @click="form.goal=g">{{ct(g)}}</button></view></view>
    <view class="coach-field"><text>{{ct('experience')}}</text><view class="coach-choices"><button v-for="g in ['beginner','regular']" :key="g" role="button" tabindex="0" :aria-pressed="form.experience===g" :class="{selected:form.experience===g}" :disabled="busy" :aria-disabled="busy" @click="form.experience=g">{{ct(g)}}</button></view></view>
    <view class="coach-field"><text>{{ct('equipment')}}</text><view class="coach-choices"><button v-for="g in ['treadmill','bike']" :key="g" role="button" tabindex="0" :aria-pressed="form.equipment.includes(g)" :class="{selected:form.equipment.includes(g)}" :disabled="busy" :aria-disabled="busy" @click="toggleEquipment(g)">{{ct(g)}}</button></view><text class="coach-hint">{{ct('none')}}</text></view>
    <button role="button" tabindex="0" class="coach-toggle limitation-toggle" :aria-pressed="form.has_limitations" :disabled="busy" :aria-disabled="busy" @click="form.has_limitations=!form.has_limitations"><view class="coach-checkbox" :class="{checked:form.has_limitations}"><AppIcon v-if="form.has_limitations" name="check" tone="white"/></view><text>{{ct('hasLimitations')}}</text></button>
    <view class="coach-field"><text>{{ct('limitations')}}</text><textarea v-model="form.limitations" maxlength="500" :placeholder="ct('limitationsHint')" :disabled="busy" :aria-disabled="busy"/></view>
    <button role="button" tabindex="0" class="coach-toggle profile-consent" :aria-pressed="form.ai_consent" :disabled="busy" :aria-disabled="busy" @click="form.ai_consent=!form.ai_consent"><view class="coach-checkbox" :class="{checked:form.ai_consent}"><AppIcon v-if="form.ai_consent" name="check" tone="white"/></view><text>{{ct('profileConsent')}}</text></button>
    <text class="coach-privacy">{{ct('privacy')}}</text>
    <button role="button" tabindex="0" class="coach-primary save-health" :disabled="busy" :aria-disabled="busy" @click="saveHealth">{{ct('save')}}</button><text v-if="saved&&!dirty" class="coach-saved">{{ct('saved')}}</text>
    <button v-if="saved" role="button" tabindex="0" class="coach-link coach-delete" :disabled="busy" :aria-disabled="busy" @click="deleteOpen=true">{{ct('remove')}}</button>
   </view>
   <view class="coach-main">
    <view class="coach-panel coach-chat">
     <view class="coach-section-row"><text class="coach-section-title">{{ct('chat')}}</text><text v-if="status.configured" class="coach-model">{{status.model}}</text></view>
     <text v-if="!status.configured" class="coach-warning">{{ct('unconfigured')}}</text>
     <text v-if="!run" class="coach-hint">{{ct('empty')}}</text>
     <view v-if="run" class="coach-conversation"><view class="coach-user-message"><text class="coach-message-label">{{ct('request')}}</text><text>{{run.message}}</text></view><view class="coach-ai-message"><text class="coach-message-label">{{ct('ai')}} · {{ct(run.status)}}</text><text v-if="working">{{ct('generating')}}</text><text v-else-if="run.error_code">{{ct(run.error_code)}}</text><text v-else-if="run.answer">{{run.answer}}</text><text v-if="run.status==='needs_input'" class="coach-hint">{{ct('followup')}}</text></view></view>
     <button v-if="run?.proposal||run?.candidate_text" role="button" class="coach-secondary view-draft" @click="draftOpen=true">{{ct('viewDraft')}}</button>
     <view v-if="run?.validation_issues?.length" class="coach-warning"><text>{{ct('validationReasons')}}</text><text v-for="(issue,i) in run.validation_issues" :key="i" class="coach-issue">{{i+1}}. {{locale==='en'?issue.en:issue.zh}}</text></view>
     <text v-if="run?.status==='failed'&&!run?.candidate_text&&!run?.proposal" class="coach-hint">{{ct('noDraftSaved')}}</text>
     <view class="coach-composer" :class="{'coach-reply':needsReply}">
     <view class="coach-field"><text class="coach-input-label">{{ct(needsReply?'replyLabel':'prompt')}}</text><text v-if="needsReply" class="coach-hint">{{ct('replyHint')}}</text><textarea v-model="message" maxlength="2000" class="coach-prompt" :class="{'coach-reply-input':needsReply}" :aria-label="ct(needsReply?'replyLabel':'prompt')" :cursor-spacing="24" :placeholder="ct(needsReply?'replyPlaceholder':'promptPlaceholder')" :disabled="working||busy" :aria-disabled="working||busy"/></view>
     <view v-if="!needsReply" class="coach-field"><text>{{ct('start')}}</text><input class="coach-date" v-model="startDate" maxlength="10" placeholder="YYYY-MM-DD" :disabled="working||busy" :aria-disabled="working||busy"/></view>
     <button role="button" tabindex="0" class="coach-toggle run-consent" :aria-pressed="shareThisRun" :disabled="working||busy" :aria-disabled="working||busy" @click="shareThisRun=!shareThisRun"><view class="coach-checkbox" :class="{checked:shareThisRun}"><AppIcon v-if="shareThisRun" name="check" tone="white"/></view><text>{{ct('share')}}</text></button>
     <text v-if="dirty&&saved" class="coach-warning">{{ct('editHint')}}</text>
     <view class="coach-actions"><button role="button" tabindex="0" class="coach-primary generate-plan" :disabled="!canGenerate" :aria-disabled="!canGenerate" @click="generate">{{ct(working?'generating':needsReply?'sendReply':'generate')}}</button><button v-if="run&&['queued','running','draft'].includes(run.status)" role="button" tabindex="0" class="coach-secondary" :disabled="busy" :aria-disabled="busy" @click="cancelRun">{{ct('cancelRun')}}</button></view>
     <text class="coach-hint">{{ct('budget')}}</text>
     </view>
     <view v-if="run?.tool_log?.length" class="coach-tools"><text class="coach-message-label">{{ct('tools')}}</text><view v-for="(event,i) in run.tool_log" :key="i"><AppIcon :name="['completed','validated','committed'].includes(event.status)?'check':'close'"/><text>{{ct('tool_'+event.tool)}}</text><text v-if="!['completed','validated','committed'].includes(event.status)">{{ct(event.status)}}</text></view></view>
    </view>
    <view v-if="run?.proposal" class="coach-panel coach-draft"><view class="coach-section-row"><text class="coach-section-title">{{ct('preview')}}</text><text class="coach-badge">{{ct(run.status)}}</text></view><text class="coach-hint">{{ct(run.status==='committed'?'committed':'draftNotice')}}</text><view v-for="(p,i) in run.proposal.sessions" :key="i" class="coach-session"><view class="coach-session-heading"><text>{{p.date}}</text><text>{{p.target_minutes}} {{ct('minutesUnit')}}</text></view><text class="coach-plan-title">{{p.title}}</text><PlanExercises :items="p.exercises"/></view><text class="coach-hint">{{ct('doseHint')}}</text><button v-if="run.status==='draft'" role="button" tabindex="0" class="coach-primary confirm-plan" :disabled="busy||dirty" :aria-disabled="busy||dirty" @click="confirmPlan">{{ct('confirm')}}</button><view v-if="run.status==='committed'" class="coach-success"><text>{{ct('added')}}：{{run.created_plan_ids.length}}</text><button role="button" tabindex="0" class="coach-primary" @click="emit('view-plans')">{{ct('goPlans')}}</button></view></view>
    <view v-if="history.length" class="coach-panel coach-history"><text class="coach-section-title">{{ct('history')}}</text><button v-for="item in history" :key="item.id" role="button" tabindex="0" class="coach-history-row" :disabled="working||busy" :aria-disabled="working||busy" @click="selectRun(item)"><text>{{item.message}}</text><text>{{ct(item.status)}}</text></button></view>
   </view>
  </view>
  <DraftViewer v-if="draftOpen&&run" :run="run" @close="draftOpen=false"/>
  <view v-if="deleteOpen" class="coach-overlay"><view class="coach-delete-dialog"><text class="coach-section-title">{{ct('removeTitle')}}</text><text class="coach-hint">{{ct('removeHint')}}</text><view class="coach-actions"><button role="button" tabindex="0" class="coach-secondary" :disabled="busy" :aria-disabled="busy" @click="deleteOpen=false">{{ct('cancel')}}</button><button role="button" tabindex="0" class="coach-primary" :disabled="busy" :aria-disabled="busy" @click="deleteHealth">{{ct('confirmDelete')}}</button></view></view></view>
 </view>
</template>
<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import DraftViewer from './DraftViewer.vue';import AppIcon from './AppIcon.vue';import PlanExercises from './PlanExercises.vue';import {request} from '../lib/api';import {locale} from '../lib/i18n';import {ct} from '../lib/coach-i18n';
const emit=defineEmits(['created','view-plans','unauthorized']);
const defaults=()=>({age:'',height_cm:'',weight_kg:'',weekly_days:'3',session_minutes:'30',goal:'fitness',experience:'beginner',equipment:[] as string[],has_limitations:false,limitations:'',ai_consent:false});
const numericFields=[{key:'age',label:'age'},{key:'height_cm',label:'height'},{key:'weight_kg',label:'weight'},{key:'weekly_days',label:'days'},{key:'session_minutes',label:'minutes'}];
const form=ref<any>(defaults()),saved=ref(false),signature=ref(''),busy=ref(false),error=ref(''),deleteOpen=ref(false),draftOpen=ref(false),message=ref(''),shareThisRun=ref(false),history=ref<any[]>([]),run=ref<any>(null),status=ref({configured:false,model:''});
const startDate=ref(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()));
const dirty=computed(()=>signature.value!==JSON.stringify(form.value));const working=computed(()=>run.value&&['queued','running'].includes(run.value.status));
const needsReply=computed(()=>run.value?.status==='needs_input');
const canGenerate=computed(()=>status.value.configured&&saved.value&&!dirty.value&&form.value.ai_consent&&shareThisRun.value&&message.value.trim()&&!busy.value&&!working.value);
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,requestKey='',requestSignature='';
function stopPolling(){if(timer)clearTimeout(timer);timer=undefined;}
function fail(e:any){error.value=e.message||'error';if(e.message==='UNAUTHORIZED')emit('unauthorized');}
function uuid(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const n=Math.floor(Math.random()*16);return(c==='x'?n:(n&3)|8).toString(16);});}
function setProfile(p:any){if(p){form.value={...defaults(),...p};delete form.value.version;delete form.value.updated_at;for(const f of numericFields)form.value[f.key]=String(p[f.key]);saved.value=true;}else{form.value=defaults();saved.value=false;}signature.value=JSON.stringify(form.value);}
function toggleEquipment(value:string){form.value.equipment=form.value.equipment.includes(value)?form.value.equipment.filter((x:string)=>x!==value):[...form.value.equipment,value];}
async function refreshHistory(){history.value=await request('/api/agent/runs');}
async function initialize(){busy.value=true;error.value='';try{const [p,s,h]=await Promise.all([request('/api/health-profile'),request('/api/agent/status'),request('/api/agent/runs')]);if(disposed)return;setProfile(p);status.value=s;history.value=h;run.value=h[0]??null;if(working.value)poll();}catch(e){fail(e);}finally{busy.value=false;}}
async function saveHealth(){busy.value=true;error.value='';try{const body={...form.value};for(const f of numericFields)body[f.key]=Number(body[f.key]);setProfile(await request('/api/health-profile','PUT',body));stopPolling();shareThisRun.value=false;await refreshHistory();run.value=history.value[0]??null;}catch(e){fail(e);}finally{busy.value=false;}}
async function deleteHealth(){busy.value=true;error.value='';try{await request('/api/health-profile','DELETE');stopPolling();setProfile(null);run.value=null;history.value=[];message.value='';shareThisRun.value=false;deleteOpen.value=false;}catch(e){fail(e);}finally{busy.value=false;}}
async function poll(){stopPolling();if(disposed||!run.value)return;try{run.value=await request('/api/agent/runs/'+run.value.id);if(!working.value){await refreshHistory();return;}}catch(e){fail(e);return;}if(!disposed)timer=setTimeout(poll,1800);}
async function generate(){if(!canGenerate.value)return;busy.value=true;error.value='';try{const body:any={message:message.value.trim(),start_date:needsReply.value?run.value.start_date:startDate.value,locale:locale.value,consent:true};if(run.value&&['needs_input','draft'].includes(run.value.status))body.parent_id=run.value.id;const nextSignature=JSON.stringify(body);if(!requestKey||requestSignature!==nextSignature){requestKey=uuid();requestSignature=nextSignature;}body.request_key=requestKey;run.value=await request('/api/agent/runs','POST',body);requestKey='';shareThisRun.value=false;message.value='';await refreshHistory();poll();}catch(e){fail(e);}finally{busy.value=false;}}
async function cancelRun(){busy.value=true;error.value='';try{run.value=await request('/api/agent/runs/'+run.value.id+'/cancel','POST',{});stopPolling();await refreshHistory();}catch(e){fail(e);}finally{busy.value=false;}}
async function confirmPlan(){busy.value=true;error.value='';try{run.value=await request('/api/agent/runs/'+run.value.id+'/confirm','POST',{confirm:true});await refreshHistory();emit('created');}catch(e){fail(e);}finally{busy.value=false;}}
async function selectRun(item:any){draftOpen.value=false;stopPolling();run.value=item;error.value='';await poll();}
onMounted(initialize);onUnmounted(()=>{disposed=true;stopPolling();});
</script>
<style scoped>
.coach-issue{display:block;line-height:1.8;margin-top:8px;overflow-wrap:anywhere}.view-draft{margin:16px 0}

.coach-reply{border:2px solid #a5bd8f;border-radius:12px;background:#f5f9ef;padding:16px;margin:16px 0}.coach-input-label{display:block;font-size:13px;font-weight:600;color:#35563d;margin-bottom:10px}.coach-prompt{display:block;width:100%;height:125px;box-sizing:border-box;border:1px solid #dce5d4;border-radius:9px;padding:11px;background:#fafbf8;font-size:13px;line-height:1.8;color:#2f4d37}.coach-reply-input{background:white;min-height:125px}

.coach{color:#203e2e}.coach-heading{margin:0 0 25px}.coach-kicker{display:block;color:#8a9b7b;font-size:10px;letter-spacing:2px;margin-bottom:12px}.coach-title{display:block;font-size:30px;font-weight:700;line-height:1.4}.coach-subtitle{display:block;margin-top:10px;color:#7b8b70;font-size:13px}.coach-layout{display:grid;grid-template-columns:minmax(290px,.8fr) minmax(0,1.2fr);gap:24px;align-items:start}.coach-panel{background:#fff;border:1px solid #dfe7d9;border-radius:18px;padding:25px;min-width:0}.coach-section-title{display:block;font-size:17px;font-weight:650;line-height:1.5}.coach-section-row{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.coach-hint{display:block;color:#87917d;font-size:11px;line-height:1.8;margin:10px 0}.coach-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.coach-field{margin:16px 0}.coach-field>text{display:block;font-size:11px;color:#687e5d;margin-bottom:8px}.coach-field input,.coach-field textarea{display:block;width:100%;border:1px solid #dce5d4;border-radius:9px;padding:11px;background:#fafbf8;color:#2f4d37;font-size:13px;min-height:43px;box-sizing:border-box}.coach-field textarea{height:105px;line-height:1.8}.coach-field .coach-prompt{height:125px}.coach-choices{display:flex;gap:6px;flex-wrap:wrap}.coach-choices button{margin:0;background:#f1f5ec;color:#7b8d6c;font-size:11px;line-height:20px;padding:8px 10px;border-radius:8px}.coach-choices .selected{background:#dfeccf;color:#305238}.coach-toggle{display:flex;align-items:flex-start;gap:10px;background:transparent;text-align:left;padding:6px 0;margin:10px 0;color:#58734b;font-size:11px;line-height:1.8}.coach-checkbox{width:18px;height:18px;flex-shrink:0;border:1px solid #b8c8aa;border-radius:5px;display:flex;align-items:center;justify-content:center;margin-top:1px}.coach-checkbox.checked{background:#496d3c;border-color:#496d3c}.coach-checkbox .icon{font-size:13px}.coach-privacy{display:block;font-size:10px;color:#8b967e;line-height:1.8;margin:10px 0 17px}.coach-primary,.coach-secondary{margin:0;border-radius:9px;padding:11px 16px;font-size:12px;line-height:22px;white-space:normal}.coach-primary{background:#284f39;color:white}.coach-primary[disabled]{opacity:.45;background:#496c48;color:#fff}.coach-secondary{background:#edf3e6;color:#547347}.coach-link{margin:0;background:transparent;color:#718861;font-size:11px;padding:4px 0;line-height:1.8;white-space:normal}.coach-delete{margin-top:12px;color:#97756c;text-align:left}.coach-saved{display:block;color:#6d8c59;font-size:11px;margin-top:10px}.coach-main{display:flex;flex-direction:column;gap:22px;min-width:0}.coach-model,.coach-badge{font-size:10px;border-radius:6px;background:#ebf3e1;color:#66864d;padding:5px 8px;overflow-wrap:anywhere}.coach-error,.coach-warning{display:block;border-radius:9px;background:#fff3e8;color:#976948;padding:12px;font-size:12px;line-height:1.8;margin:12px 0}.coach-error{display:flex;justify-content:space-between;gap:12px}.coach-actions{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.coach-user-message,.coach-ai-message{border-radius:12px;padding:16px;margin:18px 0;font-size:13px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.coach-user-message{background:#edf3e5}.coach-ai-message{background:#f7f8f3;border:1px solid #e7ebdf}.coach-message-label{display:block;font-size:10px;color:#839571;margin-bottom:8px}.coach-tools{padding:10px 0}.coach-tools>view{display:flex;align-items:center;gap:7px;font-size:10px;line-height:1.8;color:#7a8c6b;flex-wrap:wrap}.coach-tools .icon{font-size:13px}.coach-session{margin-top:20px;padding:15px;border:1px solid #e2e9db;border-radius:12px}.coach-session-heading{display:flex;justify-content:space-between;gap:10px;color:#8a967d;font-size:11px;margin-bottom:10px}.coach-plan-title{display:block;font-size:15px;font-weight:600}.coach-success{margin-top:20px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#547841;font-size:13px;flex-wrap:wrap}.coach-history-row{background:transparent;display:flex;justify-content:space-between;gap:15px;padding:12px 0;border-bottom:1px solid #edf0e6;font-size:11px;line-height:1.7;color:#6a805d;text-align:left}.coach-history-row>text:first-child{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.coach-history-row>text:last-child{flex-shrink:0}.coach-overlay{position:fixed;inset:0;background:#152b2260;z-index:150;display:flex;align-items:center;justify-content:center;padding:20px}.coach-delete-dialog{max-width:440px;width:100%;padding:28px;background:white;border-radius:18px}
@media(max-width:1180px){.coach-layout{grid-template-columns:1fr}.coach-profile .coach-fields{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:760px){.coach-panel{padding:20px 16px}.coach-title{font-size:25px}.coach-subtitle{font-size:12px;line-height:1.8}.coach-profile .coach-fields{grid-template-columns:1fr 1fr}.coach-session{padding:12px}.coach-primary,.coach-secondary{font-size:11px}.coach-section-title{font-size:16px}}
</style>
